import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) =>
  ({ id, text, priority, required });
const frame = s => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';
const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });

test('reject invalid fields and budgets even with zero budget', () => {
  for (const budget of [-1, 0.5, NaN, Infinity, 2 ** 53, '0', null, undefined]) {
    assert.throws(() => packContext([], budget), Error);
  }
  for (const sections of [null, {}, 'x', [null], [[]], [1], new Array(1)]) {
    assert.throws(() => packContext(sections, 0), Error);
  }
  for (const [key, values] of Object.entries({
    id: ['', 1, null, undefined], text: [1, null, undefined],
    priority: [-1, 0.1, Infinity, 2 ** 53, '1', null, undefined],
    required: [0, 1, 'true', null, undefined],
  })) {
    for (const value of values) {
      assert.throws(() => packContext([section('ok'), { ...section('bad'), [key]: value }], 0), Error);
    }
    const missing = section('missing');
    delete missing[key];
    assert.throws(() => packContext([missing], 0), Error);
  }
});

test('preserve unusual IDs, exact framing, and frozen input', () => {
  const input = Object.freeze(['__proto__', ' ', 'A', 'a', '\n\0雪"\\']
    .map(id => Object.freeze(section(id, ' \r\n😀\0 '))));
  const text = input.map(frame).join('');
  const bytes = Buffer.byteLength(text, 'utf8');
  assert.deepEqual(packContext(input, bytes), {
    text, bytes, included: input.map(s => s.id), omitted: [],
  });
  assert.equal(packContext(input, Number.MAX_SAFE_INTEGER).bytes, bytes);
});

test('required order, stable optional order, skipped frames, and omission order', () => {
  const input = [section('low', 'x'.repeat(100), 1), section('r1', '', 0, true),
    section('high', 'x'.repeat(100), 100), section('tie1', '', 5),
    section('r2', '', 99, true), section('tie2', '', 5), section('small', '', 0)];
  const chosen = [input[1], input[4], input[3], input[5], input[6]];
  const text = chosen.map(frame).join('');
  assert.deepEqual(packContext(input, Buffer.byteLength(text)), {
    text, bytes: Buffer.byteLength(text), included: chosen.map(s => s.id), omitted: ['low', 'high'],
  });
  assert.throws(() => packContext(input, Buffer.byteLength(frame(input[1]))), Error);
});

test('CLI success and failures use the specified streams and status', () => {
  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
  try {
    const path = join(dir, 'input.json');
    const input = { sections: [section('雪', 'é')], maxBytes: 100, ignored: true };
